#!/usr/bin/env bash
# Kolo end-to-end smoke flow against a deployed stack (fork dry run OR real mainnet demo).
#   Dry run:  RPC_URL=http://127.0.0.1:8599 DRY_RUN=1 STATE_FILE=… GAS_TSV=… ./scripts/mainnet-smoke.sh
#   Real:     CONFIRM_MAINNET=yes ./scripts/mainnet-smoke.sh     (spends real USDC: ~0.7 USDC moved + gas)
# Actors come from ~/.kolo/mainnet-demo-wallets.env (throwaway wallets generated by us; keys never printed).
# Contributions are 0.05–0.10 USDC. Writes per-step gas to $GAS_TSV (step, gasUsed, usdcTransfers, usdcApprovals).
set -euo pipefail; set +x; export PATH=$HOME/.foundry/bin:$PATH; cd "$(dirname "$0")/.."
STATE=${STATE_FILE:-../notes/mainnet-deployment.json}; GAS_TSV=${GAS_TSV:-../notes/mainnet-smoke-gas.tsv}
RPC_URL=${RPC_URL:-https://rpc.mainnet.arc.io}; DRY_RUN=${DRY_RUN:-0}; export ETH_RPC_URL=$RPC_URL
if [[ $DRY_RUN == 1 ]]; then [[ "$RPC_URL" == http://127.0.0.1:* ]] || { echo "DRY_RUN needs local fork"; exit 1; }
else [[ "${CONFIRM_MAINNET:-}" == yes ]] || { echo "set CONFIRM_MAINNET=yes"; exit 1; }; fi
set -a; . ~/.kolo/mainnet-demo-wallets.env; set +a
USDC=0x3600000000000000000000000000000000000000
TRANSFER_T=$(cast keccak "Transfer(address,address,uint256)"); APPROVAL_T=$(cast keccak "Approval(address,address,uint256)")
get(){ jq -r --arg k "$1" '.[$k]' "$STATE"; }
F=$(get factory); SCHOOL_ID=$(get payee_school)
PASS=0; FAIL=0; : > "$GAS_TSV"
[[ "$(cast chain-id)" == 5042 ]] || exit 1

# send <name> <pk-var> <to> <sig> [args…] — records gas; fails the run on revert
send(){ local name=$1 pkv=$2 to=$3; shift 3; local out
  out=$(cast send "$to" "$@" --private-key "${!pkv}" --json 2>&1) || { echo "FAIL $name: ${out:0:160}"; FAIL=$((FAIL+1)); return 1; }
  local gu tr ap
  gu=$(jq -r '.gasUsed' <<<"$out"); gu=$((gu))
  tr=$(jq --arg u "${USDC,,}" --arg t "$TRANSFER_T" '[.logs[]|select((.address|ascii_downcase)==$u and .topics[0]==$t)]|length' <<<"$out")
  ap=$(jq --arg u "${USDC,,}" --arg t "$APPROVAL_T" '[.logs[]|select((.address|ascii_downcase)==$u and .topics[0]==$t)]|length' <<<"$out")
  printf '%s\t%s\t%s\t%s\n' "$name" "$gu" "$tr" "$ap" >> "$GAS_TSV"
  echo "PASS $name"; PASS=$((PASS+1)); }
bal(){ cast call $USDC "balanceOf(address)(uint256)" "$1" | awk '{print $1}'; }
check(){ if [[ "$2" == "$3" ]]; then echo "PASS check $1 = $2"; PASS=$((PASS+1)); else echo "FAIL check $1: got $2 want $3"; FAIL=$((FAIL+1)); fi; }

# ── fund actors ───────────────────────────────────────────────────────────────────────
if [[ $DRY_RUN == 1 ]]; then
  for a in $DEMO_ORG_ADDRESS $DEMO_COSIGNER1_ADDRESS $DEMO_COSIGNER2_ADDRESS; do cast rpc anvil_setBalance $a 0x6F05B59D3B20000 >/dev/null; done  # 0.5 native
  for a in $DEMO_ORG_ADDRESS $DEMO_COSIGNER1_ADDRESS $DEMO_COSIGNER2_ADDRESS; do
    cast send $USDC "mint(address,uint256)" $a 1000000 --private-key "$DEMO_ORG_PK" >/dev/null
  done
else
  . scripts/lib-deployer-signer.sh
  for pair in "$DEMO_ORG_ADDRESS 400000" "$DEMO_COSIGNER1_ADDRESS 300000" "$DEMO_COSIGNER2_ADDRESS 300000"; do set -- $pair
    cast send $USDC "transfer(address,uint256)" "$1" "$2" "${SIGN[@]}" >/dev/null; echo "funded $1 with $2 (6-dec units)"; done
fi
NOW=$(date +%s); DL=$((NOW+86400*7))
ORG=DEMO_ORG_PK; C1=DEMO_COSIGNER1_PK; C2=DEMO_COSIGNER2_PK

# ── GroupPot: 2-of-2 co-signers, raw vendor payee, milestone cap 0.30 ───────────────
P=$(cast abi-encode "f(address,address,address,uint256,bytes32,uint128,uint96,uint40,bool,uint8,address[],uint256[],address[],bytes32[],uint8[],uint128[])" \
  $DEMO_ORG_ADDRESS $USDC $F 0 $(cast keccak "Mainnet smoke pot") 300000 0 $DL true 2 "[$DEMO_COSIGNER1_ADDRESS,$DEMO_COSIGNER2_ADDRESS]" "[0]" "[$DEMO_VENDOR_ADDRESS]" "[$(cast format-bytes32-string deposit)]" "[0]" "[300000]")
send createGroupPot $ORG $F "createGroupPot(bytes)" $P
ID=$(cast call $F "potCount()(uint256)" | awk '{print $1}'); POT=$(cast call $F "potAddress(uint256)(address)" $ID); echo "GroupPot #$ID $POT"
for v in ORG C1 C2; do send approve-$v ${!v} $USDC "approve(address,uint256)" $POT 300000; done
send contribute-ORG $ORG $POT "contribute(uint128,bytes32)" 100000 $(cast keccak memo1)
send contribute-C1  $C1  $POT "contribute(uint128,bytes32)" 100000 $(cast keccak memo2)
send subscribe-C2   $C2  $POT "subscribe(uint96,uint32,uint32)" 50000 86400 3
send pull-sub1      $ORG $POT "pull(uint256)" 1
send contribute-C2  $C2  $POT "contribute(uint128,bytes32)" 50000 $(cast keccak memo3)
check totalContributed "$(cast call $POT 'totalContributed()(uint128)' | awk '{print $1}')" 300000
send submitInvoice  $ORG $POT "submitInvoice(uint8,uint8,uint248,bytes32,bytes32)" 0 0 100000 $(cast keccak invoice.pdf) $(cast format-bytes32-string uri1)
send approve-inv-C1 $C1  $POT "approve(uint256)" 1
send approve-inv-C2 $C2  $POT "approve(uint256)" 1
V0=$(bal $DEMO_VENDOR_ADDRESS)
send release        $ORG $POT "release(uint256)" 1
check vendor-received $(( $(bal $DEMO_VENDOR_ADDRESS) - V0 )) 100000
send close          $ORG $POT "close()"
send approveClose   $C1  $POT "approveClose()"
for v in ORG C1 C2; do send claimRefund-$v ${!v} $POT "claimRefund()"; done
check group-pot-empty "$(bal $POT)" 0

# ── TuitionPot: verified school payee, 2 terms, 1-of-1 co-signer ───────────────────
T=$(cast abi-encode "f(address,address,address,uint256,bytes32,uint96,uint40,bool,uint256,uint8,address[],uint40[],uint128[])" \
  $DEMO_ORG_ADDRESS $USDC $F 0 $(cast keccak "Mainnet smoke tuition") 0 $DL true $SCHOOL_ID 1 "[$DEMO_COSIGNER1_ADDRESS]" "[$((NOW+3600)),$((NOW+7200))]" "[50000,50000]")
send createTuitionPot $ORG $F "createTuitionPot(bytes)" $T
TID=$(cast call $F "potCount()(uint256)" | awk '{print $1}'); TP=$(cast call $F "potAddress(uint256)(address)" $TID); echo "TuitionPot #$TID $TP"
send t-approve-ORG $ORG $USDC "approve(address,uint256)" $TP 300000
send t-approve-C1  $C1  $USDC "approve(address,uint256)" $TP 300000
send t-contribute-ORG $ORG $TP "contribute(uint128,bytes32)" 70000 $(cast keccak t1)
send t-contribute-C1  $C1  $TP "contribute(uint128,bytes32)" 50000 $(cast keccak t2)
S0=$(bal $DEMO_SCHOOL_ADDRESS)
send payTerm0 $C2 $TP "payTerm(uint8)" 0
send payTerm1 $C2 $TP "payTerm(uint8)" 1
check school-received $(( $(bal $DEMO_SCHOOL_ADDRESS) - S0 )) 100000
send t-claimRefund-ORG $ORG $TP "claimRefund()" || send t-close $ORG $TP "close(bytes)" 0x
send t-claimRefund-C1  $C1  $TP "claimRefund()" || true
echo "tuition pot balance: $(bal $TP)"
echo "globalStats (locked, released, refunded): $(cast call $F "globalStats()(uint256,uint256,uint256)" | tr "\n" " ")"
echo "RESULT pass=$PASS fail=$FAIL"; [[ $FAIL == 0 ]]
